#include <array>
#include <cstddef>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <limits>
#include <span>
#include <stdexcept>
#include <vector>

// Supplied implementation: returns the stored CRC32C checksum value.
std::uint32_t crc32c(std::span<const std::byte> bytes);

static bool read_exact(std::istream& in, std::byte* dst,
                       std::size_t count) {
    if (count == 0) return true;
    in.read(reinterpret_cast<char*>(dst),
            static_cast<std::streamsize>(count));
    if (in.bad() || (in.fail() && !in.eof()))
        throw std::runtime_error("log I/O failure");
    return in.gcount() == static_cast<std::streamsize>(count);
}

static std::uint32_t le32(const std::byte* p) {
    std::uint32_t result = 0;
    for (unsigned i = 0; i < 4; ++i)
        result |= std::uint32_t(std::to_integer<unsigned char>(p[i]))
                  << (8u * i);
    return result;
}

static std::uint64_t le64(const std::byte* p) {
    std::uint64_t result = 0;
    for (unsigned i = 0; i < 8; ++i)
        result |= std::uint64_t(std::to_integer<unsigned char>(p[i]))
                  << (8u * i);
    return result;
}

// Preconditions: binary input positioned at byte zero;
// stream exceptions disabled; log unchanged during recovery.
std::uint64_t recover(std::istream& in) {
    constexpr std::uint32_t max_payload = 1u << 20;
    constexpr std::uint64_t maximum =
        std::numeric_limits<std::uint64_t>::max();
    static_assert(std::numeric_limits<std::streamsize>::max()
                  >= max_payload);

    std::uint64_t valid_end = 0;
    std::uint64_t expected_sequence = 0;
    std::array<std::byte, 12> header{};
    std::array<std::byte, 4> checksum{};
    std::vector<std::byte> crc_input;

    for (;;) {
        if (!read_exact(in, header.data(), header.size()))
            return valid_end;

        const auto length = le32(header.data());
        const auto sequence = le64(header.data() + 4);
        if (length > max_payload || sequence != expected_sequence)
            return valid_end;

        // 4 length bytes + 8 sequence bytes + payload + 4 CRC bytes.
        const std::uint64_t record_size =
            std::uint64_t{16} + std::uint64_t{length};
        if (record_size > maximum - valid_end)
            throw std::overflow_error("byte offset exceeds uint64_t");

        // At most 1 MiB + 8 bytes; length was checked before allocation.
        crc_input.resize(std::size_t{8} +
                         static_cast<std::size_t>(length));
        for (std::size_t i = 0; i < 8; ++i)
            crc_input[i] = header[4 + i];

        if (!read_exact(in, crc_input.data() + 8, length))
            return valid_end;
        if (!read_exact(in, checksum.data(), checksum.size()))
            return valid_end;
        if (crc32c(std::span<const std::byte>(
                crc_input.data(), crc_input.size()))
                != le32(checksum.data()))
            return valid_end;

        valid_end += record_size;
        if (expected_sequence == maximum)
            return valid_end; // No subsequent sequence is permitted.
        ++expected_sequence;
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: recover LOG\n";
        return 1;
    }
    try {
        std::ifstream input(argv[1], std::ios::binary);
        if (!input.is_open())
            throw std::runtime_error("cannot open log");
        std::cout << recover(input) << '\n';
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
