#include <cstddef>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>

// Supplied implementation: standard CRC-32C of these bytes.
std::uint32_t crc32c(const std::uint8_t* data, std::size_t size);

static bool read_exact(std::istream& in, std::uint8_t* dst,
                       std::size_t size) {
    if (size == 0) return true;
    // Every call below is at most 1 MiB + 8 bytes.
    if (size > static_cast<std::uintmax_t>(
                   std::numeric_limits<std::streamsize>::max()))
        throw std::runtime_error("read size is not representable");
    const auto requested = static_cast<std::streamsize>(size);
    in.read(reinterpret_cast<char*>(dst), requested);
    return in.gcount() == requested && !in.fail();
}

static std::uint32_t le32(const std::uint8_t* p) {
    std::uint32_t value = 0;
    for (unsigned i = 0; i < 4; ++i)
        value |= std::uint32_t{p[i]} << (8u * i);
    return value;
}

static std::uint64_t le64(const std::uint8_t* p) {
    std::uint64_t value = 0;
    for (unsigned i = 0; i < 8; ++i)
        value |= std::uint64_t{p[i]} << (8u * i);
    return value;
}

// Precondition: input starts at byte zero of a stable binary log.
// Returns the exclusive end offset of the validated prefix.
std::uint64_t recover(std::istream& in) {
    constexpr std::uint32_t max_payload = 1024u * 1024u;
    constexpr auto max_offset =
        std::numeric_limits<std::uint64_t>::max();

    std::uint64_t offset = 0;
    std::uint64_t expected_sequence = 0;
    std::array<std::uint8_t, 4> length_bytes{};
    std::array<std::uint8_t, 4> checksum_bytes{};
    std::vector<std::uint8_t> encoded;

    for (;;) {
        if (!read_exact(in, length_bytes.data(), length_bytes.size()))
            return offset;

        const std::uint32_t length = le32(length_bytes.data());
        if (length > max_payload) return offset;

        // Widen before addition: length + sequence + length field + CRC.
        const std::uint64_t record_size = std::uint64_t{length} + 16u;
        if (record_size > max_offset - offset) return offset;

        const std::uint64_t encoded_size = std::uint64_t{length} + 8u;
        if (encoded_size > std::numeric_limits<std::size_t>::max())
            throw std::runtime_error("buffer size is not representable");
        encoded.resize(static_cast<std::size_t>(encoded_size));

        // First eight bytes are the original little-endian sequence bytes.
        if (!read_exact(in, encoded.data(), 8)) return offset;
        if (le64(encoded.data()) != expected_sequence) return offset;

        if (!read_exact(in, encoded.data() + 8, length)) return offset;
        if (!read_exact(in, checksum_bytes.data(), checksum_bytes.size()))
            return offset;

        if (crc32c(encoded.data(), encoded.size()) !=
            le32(checksum_bytes.data()))
            return offset;

        // Commit the boundary only after every check has succeeded.
        offset += record_size;

        // UINT64_MAX is legal, but no successor is: never wrap to zero.
        if (expected_sequence == max_offset) return offset;
        ++expected_sequence;
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: recover LOGFILE\n";
        return 1;
    }
    try {
        std::ifstream in(argv[1], std::ios::binary);
        if (!in.is_open()) {
            std::cerr << "Cannot open log\n";
            return 1;
        }
        const auto offset = recover(in);
        // Do not present an underlying I/O failure as successful recovery.
        if (in.bad()) {
            std::cerr << "Log read failed\n";
            return 1;
        }
        std::cout << offset << '\n';
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
