        const std::uint64_t covered_size = std::uint64_t{length} + 8u;
        if (covered_size > std::numeric_limits<std::size_t>::max())
            throw std::runtime_error("buffer size is not representable");
        covered.resize(static_cast<std::size_t>(covered_size));

        // Retain the original little-endian sequence bytes for the CRC.
        if (!read_exact(in, covered.data(), 8))
            return valid_end;
        const std::uint64_t sequence = load_le64(covered.data());
        if (sequence != expected_sequence)
            return valid_end;

        if (!read_exact(in, covered.data() + 8,
                        static_cast<std::size_t>(length)))
            return valid_end;
        if (!read_exact(in, crc_bytes.data(), crc_bytes.size()))
            return valid_end;
        if (crc32c(covered.data(), covered.size()) !=
            load_le32(crc_bytes.data()))
            return valid_end;

        // Commit the offset only after every check succeeds.
        valid_end += record_size;
        if (expected_sequence == max_offset)
            sequence_exhausted = true;
        else
            ++expected_sequence;
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: recover LOG_FILE\n";
        return 1;
    }
    try {
        std::ifstream input(argv[1], std::ios::binary);
        if (!input)
            throw std::runtime_error("cannot open log");
        std::cout << recover(input) << '\n';
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
