Correctness: initially, offset zero describes an empty valid prefix and the expected sequence is zero. Each iteration checks the bounded length, representable record end, complete reads, exact next sequence, and CRC over the encoded sequence plus payload. Only success extends the prefix; every failed validation or short read returns the previous offset immediately, without searching ahead. Sequence UINT64_MAX may be accepted once, but no following record is accepted and no sequence increment wraps. Empty payloads are valid, and an empty file returns zero.

For an intact prefix followed by an absent or detectably torn record, this returns the intact prefix’s end. It cannot distinguish clean EOF from a missing suffix, prove a record was acknowledged or durably committed, or exclude CRC collisions; length is also outside the specified checksum coverage. Therefore a torn or corrupted record that happens to satisfy all checks can be accepted. The returned offset is the end of the validated prefix, not necessarily the current stream position; truncation or replay is a separate operation.

For an exact edge count, min-plus exponentiation gives a finite optimum or impossibility—even with negative cycles. The witness is a DAG of concatenations, not an expanded walk, and any indexed edge can be retrieved in O(log(L + 1)) time. Keep lowercase statuses: `finite` and `unreachable`; `unbounded` cannot occur for a fixed finite L.

```python
class EdgeWitness:
    """Compressed directed walk. Edge IDs are input positions.

    Node tuple: (start, end, length, cost, left, right, edge_id).
    Empty node: length == 0.
    Leaf: length == 1, edge_id is an input position.
    Concatenation: left and right are earlier node IDs.
    """
    def __init__(self, edges, nodes, root):
        self.edges = edges
        self.nodes = nodes
        self.root = root

    @property
    def length(self):
        return self.nodes[self.root][2]

    @property
    def cost(self):
        return self.nodes[self.root][3]

    def edge_at(self, index):
        """Return the zero-based indexed edge ID without expansion."""
        if (not isinstance(index, int) or isinstance(index, bool)
                or not 0 <= index < self.length):
            raise IndexError('edge index out of range')
        node_id = self.root
        while True:
            node = self.nodes[node_id]
            if node[6] is not None:
                return node[6]
            left, right = node[4], node[5]
            left_length = self.nodes[left][2]
            if index < left_length:
                node_id = left
            else:
                index -= left_length
                node_id = right


def classify_root(N, edges, S, T, L):
    """Return (status, cost, compressed_witness).

    Minimize cost over walks using exactly L real edges.
    Impossible: ('unreachable', None, None).
    Successful: ('finite', integer_cost, EdgeWitness).
    Invalid input raises ValueError.
    """
    def integer(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not integer(N) or not 1 <= N <= 60:
        raise ValueError('require 1 <= N <= 60')
    if not (integer(S) and integer(T)
            and 0 <= S < N and 0 <= T < N):
        raise ValueError('invalid endpoints')
    if not integer(L) or not 0 <= L <= 10**18:
        raise ValueError('require 0 <= L <= 10**18')

    E = []
    chosen = [[None] * N for _ in range(N)]
    try:
        iterator = iter(edges)
    except TypeError as exc:
        raise ValueError('edges must be iterable') from exc
    for edge in iterator:
        if len(E) >= 10000:
            raise ValueError('too many edges')
        try:
            u, v, w = edge
        except (TypeError, ValueError) as exc:
            raise ValueError('expected u, v, w') from exc
        if not (integer(u) and integer(v)
                and 0 <= u < N and 0 <= v < N):
            raise ValueError('invalid endpoint')
        if not integer(w) or abs(w) > 10**12:
            raise ValueError('invalid weight')
        eid = len(E)
        E.append((u, v, w))
        old = chosen[u][v]
        if old is None or w < E[old][2]:
            chosen[u][v] = eid

    nodes = []

    def add(node):
        nodes.append(node)
        return len(nodes) - 1

    # Identity represents exactly zero edges, not real self-loops.
    result = [[None] * N for _ in range(N)]
    for v in range(N):
        result[v][v] = add((v, v, 0, 0, None, None, None))

    if L == 0:
        if S != T:
            return ('unreachable', None, None)
        witness = EdgeWitness(E, nodes, result[S][T])
        return ('finite', 0, witness)

    power = [[None] * N for _ in range(N)]
    for u in range(N):
        for v in range(N):
            eid = chosen[u][v]
            if eid is not None:
                power[u][v] = add(
                    (u, v, 1, E[eid][2], None, None, eid))
    del chosen

    def multiply(A, B):
        # Every finite A entry has the same length a;
        # every finite B entry has the same length b.
        C = [[None] * N for _ in range(N)]
        for u in range(N):
            for v in range(N):
                best = None
                best_left = best_right = None
                for midpoint in range(N):
                    left = A[u][midpoint]
                    right = B[midpoint][v]
                    if left is None or right is None:
                        continue
                    cost = nodes[left][3] + nodes[right][3]
                    if best is None or cost < best:
                        best = cost
                        best_left, best_right = left, right
                if best_left is None:
                    continue
                left, right = best_left, best_right
                # Do not introduce empty branches into the DAG.
                if nodes[left][2] == 0:
                    C[u][v] = right
                elif nodes[right][2] == 0:
                    C[u][v] = left
                else:
                    assert nodes[left][1] == nodes[right][0]
                    C[u][v] = add((
                        u, v,
                        nodes[left][2] + nodes[right][2],
                        best, left, right, None))
        return C

    remaining = L
    while remaining:
        if remaining & 1:
            result = multiply(result, power)
        remaining >>= 1
        if remaining:
            power = multiply(power, power)

    root = result[S][T]
    if root is None:
        return ('unreachable', None, None)
    witness = EdgeWitness(E, nodes, root)
    assert witness.length == L
    return ('finite', witness.cost, witness)


if __name__ == '__main__':
    status, cost, witness = classify_root(1, [], 0, 0, 0)
    assert (status, cost, witness.length) == ('finite', 0, 0)
    assert classify_root(2, [], 0, 1, 0) == (
        'unreachable', None, None)
    assert classify_root(2, [(0, 1, -7)], 0, 1, 2) == (
        'unreachable', None, None)

    E = [(0, 1, 5), (0, 1, -2), (1, 1, -3)]
    status, cost, witness = classify_root(2, E, 0, 1, 4)
    assert (status, cost) == ('finite', -11)
    assert [witness.edge_at(i) for i in range(4)] == [1, 2, 2, 2]

    # Huge witness stays compressed; the negative self-loop is real.
    status, cost, witness = classify_root(
        1, [(0, 0, -4)], 0, 0, 10**18)
    assert (status, cost) == ('finite', -4 * 10**18)
    assert witness.length == 10**18
    assert witness.edge_at(0) == 0
    assert witness.edge_at(10**18 - 1) == 0

    # Check directed continuity and cost on a small expanded example.
    vertex = 0
    total = 0
    _, expected, small = classify_root(2, E, 0, 1, 4)
    for i in range(small.length):
        u, v, w = E[small.edge_at(i)]
        assert u == vertex
        vertex = v
        total += w
    assert vertex == 1 and total == expected
    print('Tests passed')
